24	// ======================== Compute Entry ========================
25	
26	uint32_t AiInfraAttentionPioneerMetadataKernel::Compute(CpuKernelContext &ctx)
27	{
28	    if (!Prepare(ctx)) {
29	        return KERNEL_STATUS_PARAM_INVALID;
30	    }
31	    CheckIsDecode();
32	    if (!ParseAxisInfo()) {
33	        return KERNEL_STATUS_PARAM_INVALID;
34	    }
35	    SetTilingParams();
36	    ComputeSplitNBSeq();
37	    if (!GenMetaData()) {
38	        return KERNEL_STATUS_PARAM_INVALID;
39	    }
40	    return KERNEL_STATUS_OK;
41	}
