43	// ======================== Stage 1: Prepare ========================
44	
45	bool AiInfraAttentionPioneerMetadataKernel::Prepare(CpuKernelContext &ctx)
46	{
47	    actualSeqLengths_ = ctx.Input(static_cast<uint32_t>(ParamId::ACTUAL_SEQ_LENGTHS_OPTIONAL));
48	    actualSeqLengthsKv_ = ctx.Input(static_cast<uint32_t>(ParamId::ACTUAL_SEQ_LENGTHS_KV_OPTIONAL));
49	    metaData_ = ctx.Output(static_cast<uint32_t>(ParamId::META_DATA));
50	
51	    KERNEL_CHECK_NULLPTR(metaData_, false, "metadata is null");
52	    KERNEL_CHECK_NULLPTR(metaData_->GetData(), false, "metadata data is null");
53	    KERNEL_CHECK_NULLPTR(actualSeqLengths_, false, "actualSeqLengths is null");
54	    KERNEL_CHECK_NULLPTR(actualSeqLengthsKv_, false, "actualSeqLengthsKv is null");
55	
56	    bool requiredAttrs = GetAttrValue(ctx, "num_heads_q", numHeadsQ_) &&
57	                         GetAttrValue(ctx, "num_heads_kv", numHeadsKv_) &&
58	                         GetAttrValue(ctx, "head_dim_qk", headDimQK_) &&
59	                         GetAttrValue(ctx, "head_dim_v", headDimV_);
60	    GetAttrValueOpt(ctx, "soc_version", socVersion_);
61	    GetAttrValueOpt(ctx, "aic_core_num", aicCoreNum_);
62	    GetAttrValueOpt(ctx, "aiv_core_num", aivCoreNum_);
63	    if (!requiredAttrs) {
64	        return false;
65	    }
66	
67	    GetAttrValueOpt(ctx, "rope_head_dim", ropeHeadDim_);
68	    GetAttrValueOpt(ctx, "sparse_mode", sparseMode_);
69	    GetAttrValueOpt(ctx, "pre_tokens", preTokens_);
70	    GetAttrValueOpt(ctx, "next_tokens", nextTokens_);
71	    GetAttrValueOpt(ctx, "input_layout", inputLayout_);
72	    GetAttrValueOpt(ctx, "k_sink_num", kSinkNum_);
73	    GetAttrValueOpt(ctx, "block_size", blockSize_);
74	
75	    if (aicCoreNum_ == 0 || aivCoreNum_ == 0) {
76	        KERNEL_LOG_ERROR("Core num invalid: aic:%u, aiv:%u", aicCoreNum_, aivCoreNum_);
77	        return false;
78	    }
79	
80	    // Head sizes
81	    n1Size_ = numHeadsQ_;
82	    n2Size_ = (numHeadsKv_ == 0) ? n1Size_ : numHeadsKv_;
83	    if (n1Size_ == 0 || n2Size_ == 0 || n1Size_ % n2Size_ != 0) {
84	        KERNEL_LOG_ERROR("numHeadsQ(%u) must be a multiple of numHeadsKv(%u)", n1Size_, n2Size_);
85	        return false;
86	    }
87	    gSize_ = n1Size_ / n2Size_;
88	    return true;
89	}
