91	// ======================== Stage 2: CheckIsDecode ========================
92	
93	void AiInfraAttentionPioneerMetadataKernel::CheckIsDecode()
94	{
95	    constexpr uint32_t MLA_D_SIDE_QK_HEAD_DIM = 512U;
96	    constexpr uint32_t MLA_D_SIDE_ROPE_HEAD_DIM = 64U;
97	    isDecode_ = (headDimQK_ == MLA_D_SIDE_QK_HEAD_DIM) &&
98	                (headDimV_ == MLA_D_SIDE_QK_HEAD_DIM) &&
99	                (ropeHeadDim_ == MLA_D_SIDE_ROPE_HEAD_DIM);
100	}
