102	// ======================== Stage 3: ParseAxisInfo ========================
103	
104	bool AiInfraAttentionPioneerMetadataKernel::ParseAxisInfo()
105	{
106	    // batchSize from actualSeqLengths tensor shape
107	    int64_t bDim = actualSeqLengths_->GetTensorShape()->GetDimSize(0);
108	    if (bDim <= 0) {
109	        KERNEL_LOG_ERROR("actualSeqLengths shape dim0 is %ld, should be > 0", bDim);
110	        return false;
111	    }
112	    bSize_ = static_cast<uint32_t>(bDim);
113	
114	    if (!ParseActualSeqLengths()) {
115	        return false;
116	    }
117	
118	    // s1Size: max Qs, D-side multiplied by G (qSeqLens_ already contains per-batch values, D-side already * G)
119	    int64_t maxQs = 0;
120	    for (uint32_t i = 0; i < bSize_; i++) {
121	        maxQs = std::max(maxQs, qSeqLens_[i]);
122	    }
123	    s1Size_ = static_cast<uint32_t>(maxQs);
124	
125	    // s2Size: max KV seq length
126	    int64_t maxKVs = 0;
127	    for (uint32_t i = 0; i < bSize_; i++) {
128	        maxKVs = std::max(maxKVs, kvSeqLens_[i]);
129	    }
130	    s2Size_ = maxKVs;
131	
132	    // preToken / nextToken based on sparse mode
133	    if (sparseMode_ != static_cast<uint32_t>(APSparseMode::DEFAULT_MASK)) {
134	        attenMaskFlag_ = true;
135	    }
136	    if (sparseMode_ == static_cast<uint32_t>(APSparseMode::ALL_MASK)) {
137	        preToken_ = SPARSE_MODE_INT_MAX;
138	        nextToken_ = SPARSE_MODE_INT_MAX;
139	    } else if (sparseMode_ == static_cast<uint32_t>(APSparseMode::LEFT_UP_CAUSAL) ||
140	               sparseMode_ == static_cast<uint32_t>(APSparseMode::RIGHT_DOWN_CAUSAL)) {
141	        preToken_ = SPARSE_MODE_INT_MAX;
142	        nextToken_ = 0;
143	    } else {
144	        preToken_ = (preTokens_ == SPARSE_MODE_INT_MAX) ? 0 : preTokens_;
145	        nextToken_ = (nextTokens_ == SPARSE_MODE_INT_MAX) ? 0 : nextTokens_;
146	    }
147	
148	    return true;
149	}
150	
151	bool AiInfraAttentionPioneerMetadataKernel::ParseActualSeqLengths()
152	{
153	    const int64_t *qData = static_cast<const int64_t*>(actualSeqLengths_->GetData());
154	    const int64_t *kvData = static_cast<const int64_t*>(actualSeqLengthsKv_->GetData());
155	    KERNEL_CHECK_NULLPTR(qData, false, "actualSeqLengths data is null");
156	    KERNEL_CHECK_NULLPTR(kvData, false, "actualSeqLengthsKv data is null");
157	
158	    uint32_t kvDim = static_cast<uint32_t>(actualSeqLengthsKv_->GetTensorShape()->GetDimSize(0));
159	    uint32_t kvLoop = std::min(kvDim, bSize_);
160	    bool isPA = (blockSize_ > 0);
161	
162	    // Value-based validation on raw actual_seq_lengths data
163	    // Q: cumulative format (TND/TND_NTD), must be non-negative and non-decreasing
164	    for (uint32_t i = 0; i < bSize_; i++) {
165	        if (qData[i] < 0) {
166	            KERNEL_LOG_ERROR("actualSeqLengths[%u] = %ld, should >= 0", i, qData[i]);
167	            return false;
168	        }
169	        if (i >= 1 && qData[i] < qData[i - 1]) {
170	            KERNEL_LOG_ERROR("actualSeqLengths must not be decreasing (TND cumulative), "
171	                "but actualSeqLengths[%u]=%ld < actualSeqLengths[%u]=%ld",
172	                i, qData[i], i - 1, qData[i - 1]);
173	            return false;
174	        }
175	    }
176	    // KV: non-negative check; non-decreasing check for TND non-PA (p-side cumulative)
177	    for (uint32_t i = 0; i < kvLoop; i++) {
178	        if (kvData[i] < 0) {
179	            KERNEL_LOG_ERROR("actualSeqLengthsKv[%u] = %ld, should >= 0", i, kvData[i]);
180	            return false;
181	        }
182	        if (!isPA && i >= 1 && kvData[i] < kvData[i - 1]) {
183	            KERNEL_LOG_ERROR("actualSeqLengthsKv must not be decreasing (TND cumulative non-PA), "
184	                "but actualSeqLengthsKv[%u]=%ld < actualSeqLengthsKv[%u]=%ld",
185	                i, kvData[i], i - 1, kvData[i - 1]);
186	            return false;
187	        }
188	    }
189	
190	    qSeqLens_.resize(bSize_);
191	    kvSeqLens_.resize(bSize_);
192	
193	    if (IsLayoutTND()) {
194	        // TND layout: Q is cumulative → differential; KV depends on PA
195	        for (uint32_t i = 0; i < bSize_; i++) {
196	            // Q: cumulative → per-batch
197	            qSeqLens_[i] = (i == 0) ? qData[0] : (qData[i] - qData[i - 1]);
198	            // D-side: Q * G
199	            if (isDecode_) {
200	                qSeqLens_[i] *= static_cast<int64_t>(gSize_);
201	            }
202	
203	            // KV
204	            if (i < kvLoop) {
205	                kvSeqLens_[i] = kvData[i];
206	                if (!(isDecode_ && isPA) && i >= 1) {
207	                    kvSeqLens_[i] = kvData[i] - kvData[i - 1];
208	                }
209	            } else {
210	                kvSeqLens_[i] = kvSeqLens_[kvLoop - 1];
211	            }
212	        }
213	    } else {
214	        // Non-TND layouts (BSH, BSND, BNSD): direct values
215	        uint32_t qDim = static_cast<uint32_t>(actualSeqLengths_->GetTensorShape()->GetDimSize(0));
216	        for (uint32_t i = 0; i < bSize_; i++) {
217	            // Q: read from tensor (use index 0 if only 1 element)
218	            int64_t qVal = (qDim > 1) ? qData[i] : qData[0];
219	            // D-side BSH/BSND: Q * G
220	            if (isDecode_) {
221	                qVal *= static_cast<int64_t>(gSize_);
222	            }
223	            qSeqLens_[i] = qVal;
224	
225	            // KV: direct values
226	            if (i < kvLoop) {
227	                kvSeqLens_[i] = (kvDim > 1) ? kvData[i] : kvData[0];
228	            } else {
229	                kvSeqLens_[i] = kvSeqLens_[kvLoop - 1];
230	            }
231	        }
232	    }
233	
234	    // t1Size: last element of raw actual_seq_lengths
235	    // t2Size: last element of raw actual_seq_lengths_kv
236	    // These are used as GM strides in TND layout (total token count)
237	    t1Size_ = qData[bSize_ - 1];
238	    t2Size_ = kvData[kvDim - 1];
239	
240	    return true;
241	}
