243	// ======================== Stage 4: Tiling ========================
244	
245	void AiInfraAttentionPioneerMetadataKernel::SetTilingParams()
246	{
247	    // P-side: sOuterSize=128, sInnerSize=128
248	    // D-side: sOuterSize=64,  sInnerSize=128
249	    if (isDecode_) {
250	        sOuterSize_ = 64U;
251	        sInnerSize_ = 128U;
252	    } else {
253	        sOuterSize_ = 128U;
254	        sInnerSize_ = 128U;
255	    }
256	}
