258	// ======================== Split-core Helpers ========================
259	
260	void AiInfraAttentionPioneerMetadataKernel::GetPreNextTokensLeftUp(
261	    int64_t actualSeqLength, int64_t actualSeqLengthKV,
262	    int64_t &preTokensLeftUp, int64_t &nextTokensLeftUp) const
263	{
264	    auto mode = static_cast<APSparseMode>(sparseMode_);
265	    if (mode == APSparseMode::RIGHT_DOWN_CAUSAL) {
266	        preTokensLeftUp = SPARSE_MODE_INT_MAX;
267	        if (isDecode_) {
268	            nextTokensLeftUp = actualSeqLengthKV * static_cast<int64_t>(gSize_) - actualSeqLength;
269	        } else {
270	            nextTokensLeftUp = actualSeqLengthKV - actualSeqLength;
271	        }
272	    } else if (mode == APSparseMode::BAND) {
273	        if (isDecode_) {
274	            preTokensLeftUp = preToken_ * static_cast<int64_t>(gSize_) -
275	                actualSeqLengthKV * static_cast<int64_t>(gSize_) + actualSeqLength;
276	            nextTokensLeftUp = nextToken_ * static_cast<int64_t>(gSize_) +
277	                actualSeqLengthKV * static_cast<int64_t>(gSize_) - actualSeqLength;
278	        } else {
279	            preTokensLeftUp = preToken_ - actualSeqLengthKV + actualSeqLength;
280	            nextTokensLeftUp = nextToken_ + actualSeqLengthKV - actualSeqLength;
281	        }
282	    } else {
283	        if (isDecode_) {
284	            preTokensLeftUp = preToken_ * static_cast<int64_t>(gSize_);
285	            nextTokensLeftUp = nextToken_ * static_cast<int64_t>(gSize_);
286	        } else {
287	            preTokensLeftUp = preToken_;
288	            nextTokensLeftUp = nextToken_;
289	        }
290	    }
291	}
292	
293	void AiInfraAttentionPioneerMetadataKernel::FixParamWithRowInvalid(
294	    int64_t &actualSeqLength, int64_t actualSeqLengthKV,
295	    int64_t &preTokensLeftUp, int64_t &nextTokensLeftUp)
296	{
297	    int64_t nextTokensError = (nextTokensLeftUp < 0) ? -nextTokensLeftUp : 0;
298	    nextTokensError = std::min(nextTokensError, actualSeqLength);
299	
300	    int64_t preTokensError = 0;
301	    if (isDecode_) {
302	        preTokensError = (actualSeqLength > actualSeqLengthKV * static_cast<int64_t>(gSize_) + preTokensLeftUp) ?
303	            (actualSeqLength - actualSeqLengthKV * static_cast<int64_t>(gSize_) - preTokensLeftUp) : 0;
304	    } else {
305	        preTokensError = (actualSeqLength > actualSeqLengthKV + preTokensLeftUp) ?
306	            (actualSeqLength - actualSeqLengthKV - preTokensLeftUp) : 0;
307	    }
308	    preTokensError = std::min(preTokensError, actualSeqLength);
309	
310	    nextTokensLeftUp += nextTokensError;
311	    preTokensLeftUp -= nextTokensError;
312	    actualSeqLength -= nextTokensError;
313	    actualSeqLength -= preTokensError;
314	    if (nextTokensError > 0 || preTokensError > 0 || actualSeqLengthKV == 0) {
315	        needInit = true;
316	    }
317	}
