319	int64_t AiInfraAttentionPioneerMetadataKernel::ClipSInnerToken(int64_t val, int64_t lo, int64_t hi)
320	{
321	    return (val < lo) ? lo : ((val > hi) ? hi : val);
322	}
323	
324	int64_t AiInfraAttentionPioneerMetadataKernel::GetActualInnerBlockNums(
325	    int64_t sInnerIndexStart, int64_t sInnerIndexEnd, int64_t innerBlockNums) const
326	{
327	    if (sInnerIndexEnd < 0) {
328	        return 0;
329	    }
330	    if (sInnerIndexEnd < innerBlockNums) {
331	        return (sInnerIndexStart < 0) ? (sInnerIndexEnd + 1) : (sInnerIndexEnd - sInnerIndexStart + 1);
332	    }
333	    return (sInnerIndexStart < 0) ? innerBlockNums :
334	        (sInnerIndexStart < innerBlockNums ? innerBlockNums - sInnerIndexStart : 0);
335	}
336	
337	int64_t AiInfraAttentionPioneerMetadataKernel::GetCalcBlockNumsForS1G(
338	    int64_t actualSeqLength, int64_t actualSeqLengthKV,
339	    int64_t preTokensLeftUp, int64_t nextTokensLeftUp) const
340	{
341	    int64_t s2BlockNum = 0;
342	    int64_t outerBlockNums = CeilDiv(actualSeqLength, static_cast<int64_t>(sOuterSize_));
343	    for (int64_t i = 0; i < outerBlockNums; i++) {
344	        int64_t cubeSOuterOffset = i * static_cast<int64_t>(sOuterSize_);
345	        int64_t sInnerFirstToken = ClipSInnerToken(
346	            (cubeSOuterOffset - preTokensLeftUp) / static_cast<int64_t>(gSize_),
347	            0, actualSeqLengthKV);
348	        int64_t sInnerLastToken = ClipSInnerToken(
349	            CeilDiv(cubeSOuterOffset + nextTokensLeftUp + static_cast<int64_t>(sOuterSize_),
350	                    static_cast<int64_t>(gSize_)),
351	            0, actualSeqLengthKV);
352	        s2BlockNum += CeilDiv(sInnerLastToken, static_cast<int64_t>(sInnerSize_)) -
353	                      sInnerFirstToken / static_cast<int64_t>(sInnerSize_);
354	    }
355	    return s2BlockNum;
356	}
357	
358	int64_t AiInfraAttentionPioneerMetadataKernel::GetCalcBlockNumsOneHead(
359	    int64_t actualSeqLength, int64_t actualSeqLengthKV,
360	    int64_t preTokensLeftUp, int64_t nextTokensLeftUp) const
361	{
362	    int64_t outerBlockNums = CeilDiv(actualSeqLength, static_cast<int64_t>(sOuterSize_));
363	    int64_t innerBlockNums = CeilDiv(actualSeqLengthKV, static_cast<int64_t>(sInnerSize_));
364	
365	    if (!attenMaskFlag_) {
366	        return innerBlockNums * outerBlockNums;
367	    }
368	    if (isDecode_) {
369	        return GetCalcBlockNumsForS1G(actualSeqLength, actualSeqLengthKV,
370	            preTokensLeftUp, nextTokensLeftUp);
371	    }
372	    // P-side with attenMask: iterate sOuter rows
373	    int64_t totalBlockNums = 0;
374	    int64_t curPre = preTokensLeftUp;
375	    int64_t curNext = nextTokensLeftUp;
376	    for (int64_t sOuterIndex = 0; sOuterIndex < outerBlockNums; sOuterIndex++) {
377	        int64_t sInnerIndexStart = -(curPre > 0 ?
378	            CeilDiv(curPre, static_cast<int64_t>(sInnerSize_)) :
379	            curPre / static_cast<int64_t>(sInnerSize_));
380	        int64_t sInnerIndexEnd = curNext > 0 ?
381	            CeilDiv(curNext, static_cast<int64_t>(sInnerSize_)) :
382	            curNext / static_cast<int64_t>(sInnerSize_);
383	        totalBlockNums += GetActualInnerBlockNums(sInnerIndexStart, sInnerIndexEnd, innerBlockNums);
384	        curPre -= static_cast<int64_t>(sOuterSize_);
385	        curNext += static_cast<int64_t>(sOuterSize_);
386	    }
387	    return totalBlockNums;
388	}
389	
390	int64_t AiInfraAttentionPioneerMetadataKernel::SinkBlockCount(int64_t actualSeqLength) const
391	{
392	    int64_t outerBlockNums = CeilDiv(actualSeqLength, static_cast<int64_t>(sOuterSize_));
393	    int64_t sinkBlockPerS1g = CeilDiv(kSinkNum_, static_cast<int64_t>(sInnerSize_));
394	    return sinkBlockPerS1g * outerBlockNums;
395	}
