397	// ======================== Stage 5: ComputeSplitNBSeq ========================
398	
399	void AiInfraAttentionPioneerMetadataKernel::ComputeSplitNBSeq()
400	{
401	    // P-side: headNumSize = N1, D-side: headNumSize = N2
402	    uint32_t headNumSize = isDecode_ ? n2Size_ : n1Size_;
403	    uint32_t curCoreNum = aicCoreNum_;
404	
405	    // Build per-batch actual seq lengths for split
406	    // qSeqLens_ already contains D-side * G from ParseActualSeqLengths
407	    std::vector<int64_t> actualSeqLengths(bSize_);
408	    std::vector<int64_t> actualSeqLengthsKV(bSize_);
409	    for (uint32_t i = 0; i < bSize_; i++) {
410	        actualSeqLengths[i] = qSeqLens_[i];
411	        actualSeqLengthsKV[i] = kvSeqLens_[i];
412	    }
413	
414	    // Phase 1: compute totalBlockNumsOneHead
415	    int64_t totalBlockNumsOneHead = 0;
416	    int64_t sinkBlockNumberPerS1g = 0;
417	    if (kSinkNum_ > 0) {
418	        sinkBlockNumberPerS1g = CeilDiv(kSinkNum_, static_cast<int64_t>(sInnerSize_));
419	    }
420	
421	    for (uint32_t sIdx = 0; sIdx < bSize_; sIdx++) {
422	        int64_t actualSeqLengthsTmp = actualSeqLengths[sIdx];
423	        int64_t preTokensLeftUp = 0;
424	        int64_t nextTokensLeftUp = 0;
425	        GetPreNextTokensLeftUp(actualSeqLengths[sIdx], actualSeqLengthsKV[sIdx],
426	            preTokensLeftUp, nextTokensLeftUp);
427	        FixParamWithRowInvalid(actualSeqLengthsTmp, actualSeqLengthsKV[sIdx],
428	            preTokensLeftUp, nextTokensLeftUp);
429	
430	        totalBlockNumsOneHead += GetCalcBlockNumsOneHead(actualSeqLengthsTmp,
431	            actualSeqLengthsKV[sIdx], preTokensLeftUp, nextTokensLeftUp);
432	        if (kSinkNum_ > 0 && actualSeqLengthsKV[sIdx] != 0) {
433	            totalBlockNumsOneHead += SinkBlockCount(actualSeqLengthsTmp);
434	        }
435	    }
436	
437	    // Save for GenMetaData
438	    totalBlockNumsOneHead_ = totalBlockNumsOneHead;
439	
440	    // coreWightTarget: average work per core
441	    double coreWightTarget = static_cast<double>(totalBlockNumsOneHead * headNumSize) /
442	                             static_cast<double>(curCoreNum);
443	
444	    // s1OuterSize: seqSize = s1Size (already includes G for D-side)
445	    splitS1OuterSize_ = static_cast<uint32_t>(
446	        CeilDiv(static_cast<int64_t>(s1Size_), static_cast<int64_t>(sOuterSize_)));
447	
448	    // Phase 2: greedy allocation across batch x head x sOuter
449	    splitCoreEnable_.assign(AP_AIC_CORE_NUM, 0);
450	    splitBnStartIdx_.assign(AP_AIC_CORE_NUM, 0);
451	    splitGS1StartIdx_.assign(AP_AIC_CORE_NUM, 0);
452	
453	    int64_t curWight = 0;
454	    uint32_t curCore = 0;
455	    uint32_t tmpCoreNidEnd = 0;
456	    uint32_t tmpCoreSidEnd = 0;
457	    uint32_t tmpCoreSposEnd = 0;
458	
459	    // Core 0 is always enabled when there is work
460	    splitCoreEnable_[0] = 1;
461	
462	    for (uint32_t sIdx = 0; sIdx < bSize_; sIdx++) {
463	        for (uint32_t headNum = 0; headNum < headNumSize; headNum++) {
464	            int64_t preTokensLeftUp = 0;
465	            int64_t nextTokensLeftUp = 0;
466	            GetPreNextTokensLeftUp(actualSeqLengths[sIdx], actualSeqLengthsKV[sIdx],
467	                preTokensLeftUp, nextTokensLeftUp);
468	            int64_t actualSeqLength = actualSeqLengths[sIdx];
469	            int64_t actualSeqLengthKV = actualSeqLengthsKV[sIdx];
470	            FixParamWithRowInvalid(actualSeqLength, actualSeqLengthKV,
471	                preTokensLeftUp, nextTokensLeftUp);
472	
473	            int64_t outerBlockNums = CeilDiv(actualSeqLength, static_cast<int64_t>(sOuterSize_));
474	            int64_t innerBlockNums = CeilDiv(actualSeqLengthKV, static_cast<int64_t>(sInnerSize_));
475	
476	            for (int64_t sOuterIndex = 0; sOuterIndex < outerBlockNums; sOuterIndex++) {
477	                int64_t dif = static_cast<int64_t>(
478	                    coreWightTarget * static_cast<double>(curCore + 1)) - curWight;
479	
480	                // Compute actualInnerBlockNums for this sOuter row
481	                int64_t actualInnerBlockNums = 0;
482	                if (isDecode_) {
483	                    int64_t sInnerFirstToken = ClipSInnerToken(
484	                        (0 - preTokensLeftUp) / static_cast<int64_t>(gSize_),
485	                        0, actualSeqLengthKV);
486	                    int64_t sInnerLastToken = ClipSInnerToken(
487	                        CeilDiv(nextTokensLeftUp +
488	                                static_cast<int64_t>(sOuterSize_),
489	                                static_cast<int64_t>(gSize_)),
490	                        0, actualSeqLengthKV);
491	                    actualInnerBlockNums = CeilDiv(sInnerLastToken,
492	                        static_cast<int64_t>(sInnerSize_)) - sInnerFirstToken / static_cast<int64_t>(sInnerSize_);
493	                    if (kSinkNum_ > 0 && actualInnerBlockNums != 0) {
494	                        actualInnerBlockNums += sinkBlockNumberPerS1g;
495	                    }
496	                } else {
497	                    int64_t sInnerIndexStart = -(preTokensLeftUp > 0 ?
498	                        CeilDiv(preTokensLeftUp, static_cast<int64_t>(sInnerSize_)) :
499	                        preTokensLeftUp / static_cast<int64_t>(sInnerSize_));
500	                    int64_t sInnerIndexEnd = nextTokensLeftUp > 0 ?
501	                        CeilDiv(nextTokensLeftUp, static_cast<int64_t>(sInnerSize_)) :
502	                        nextTokensLeftUp / static_cast<int64_t>(sInnerSize_);
503	                    actualInnerBlockNums = GetActualInnerBlockNums(
504	                        sInnerIndexStart, sInnerIndexEnd, innerBlockNums);
505	                    if (kSinkNum_ > 0 && actualInnerBlockNums != 0) {
506	                        actualInnerBlockNums += sinkBlockNumberPerS1g;
507	                    }
508	                }
509	
510	                // Greedy: if adding this block exceeds target more than not, start new core
511	                if (actualInnerBlockNums - dif > dif &&
512	                    !(tmpCoreNidEnd == 0 && tmpCoreSidEnd == 0 && tmpCoreSposEnd == 0)) {
513	                    curCore += 1;
514	                    if (curCore < curCoreNum) {
515	                        splitCoreEnable_[curCore] = 1;
516	                        splitBnStartIdx_[curCore] =
517	                            static_cast<int32_t>(sIdx * headNumSize + headNum);
518	                        splitGS1StartIdx_[curCore] =
519	                            static_cast<int32_t>(sOuterIndex);
520	                    }
521	                }
522	                tmpCoreNidEnd = headNum + 1;
523	                tmpCoreSidEnd = sIdx + 1;
524	                tmpCoreSposEnd = static_cast<uint32_t>(sOuterIndex + 1);
525	
526	                curWight += actualInnerBlockNums;
527	                preTokensLeftUp -= static_cast<int64_t>(sOuterSize_);
528	                nextTokensLeftUp += static_cast<int64_t>(sOuterSize_);
529	            }
530	        }
531	    }
532	
533	    splitUsedCoreNum_ = std::min(curCore + 1, curCoreNum);
534	    // Set end boundary for last active core
535	    // Kernel accesses sparseStartIdx[aicIdx + 1] and bnStartIdx[aicIdx + 1],
536	    // so we need the boundary value at index [splitUsedCoreNum_]
537	    if (splitUsedCoreNum_ > 0 && splitUsedCoreNum_ < AP_AIC_CORE_NUM) {
538	        splitBnStartIdx_[splitUsedCoreNum_] = static_cast<int32_t>(bSize_ * headNumSize);
539	        splitGS1StartIdx_[splitUsedCoreNum_] = static_cast<int32_t>(tmpCoreSposEnd);
540	    }
541	}
542	
543	// ======================== Stage 6: GenMetaData ========================
544	
545	bool AiInfraAttentionPioneerMetadataKernel::GenMetaData() 
546	{
547	    detail::APMetaData* metaDataPtr =
548	        reinterpret_cast<detail::APMetaData*>(metaData_->GetData());
549	
550	    // Write per-core slots
551	    for (uint32_t i = 0; i < AP_AIC_CORE_NUM; ++i) {
552	        metaDataPtr->coreSlots[i].fields[static_cast<uint32_t>(PerCoreField::AIC_CORE_ENABLE)] = splitCoreEnable_[i];
553	        metaDataPtr->coreSlots[i].fields[static_cast<uint32_t>(PerCoreField::BN2_START_PTR)] = splitBnStartIdx_[i];
554	        metaDataPtr->coreSlots[i].fields[static_cast<uint32_t>(PerCoreField::GS1_START_PTR)] = splitGS1StartIdx_[i];
555	    }
556	
557	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::USED_CORE_NUM)] =
558	        static_cast<int32_t>(splitUsedCoreNum_);
559	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::M_BASE_SIZE)] = static_cast<int32_t>(sOuterSize_);
560	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::S_INNER_SIZE)] = static_cast<int32_t>(sInnerSize_);
561	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::S1_OUTER_SIZE)] =
562	        static_cast<int32_t>(splitS1OuterSize_);
563	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::S1_SIZE)] = static_cast<int32_t>(s1Size_);
564	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::S2_SIZE)] = static_cast<int32_t>(s2Size_);
565	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::ACTUAL_LEN_Q_DIM)] =
566	        static_cast<int32_t>(actualSeqLengths_->GetTensorShape()->GetDimSize(0));
567	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::ACTUAL_LEN_KV_DIM)] =
568	        static_cast<int32_t>(actualSeqLengthsKv_->GetTensorShape()->GetDimSize(0));
569	
570	    // multiSmaxsInnerLoopTimes: max across batches of CeilDiv(kvSeqLen, sInnerSize)
571	    uint32_t multiSmaxsInnerLoopTimes = 0;
572	    for (uint32_t i = 0; i < bSize_; i++) {
573	        uint32_t sInnerLoopTimes = static_cast<uint32_t>(
574	            CeilDiv(kvSeqLens_[i], static_cast<int64_t>(sInnerSize_)));
575	        multiSmaxsInnerLoopTimes = std::max(multiSmaxsInnerLoopTimes, sInnerLoopTimes);
576	    }
577	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::MULTI_SMAX_S_INNER_LOOP_TIMES)] =
578	        static_cast<int32_t>(multiSmaxsInnerLoopTimes);
579	
580	    // actualCoreNums: vector cores = cube cores * CV_RATIO
581	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::ACTUAL_CORE_NUMS)] =
582	        static_cast<int32_t>(splitUsedCoreNum_ * AP_CV_RATIO);
583	
584	    // totalSize, splitFactorSize, splitFactorTailSize
585	    uint32_t headNumSize = isDecode_ ? n2Size_ : n1Size_;
586	    int64_t sinnerBlockNum = CeilDiv(s2Size_, static_cast<int64_t>(sInnerSize_));
587	    int64_t totalSize = (sinnerBlockNum > 0) ?
588	        (totalBlockNumsOneHead_ / sinnerBlockNum) * static_cast<int64_t>(headNumSize) : 0;
589	    int64_t splitFactorSize = (splitUsedCoreNum_ > 0) ?
590	        CeilDiv(totalSize, static_cast<int64_t>(splitUsedCoreNum_)) : 0;
591	    int64_t splitFactorTailSize = (splitFactorSize > 0) ?
592	        ((totalSize % splitFactorSize != 0) ? (totalSize % splitFactorSize) : splitFactorSize) : 0;
593	
594	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::TOTAL_SIZE)] = static_cast<int32_t>(totalSize);
595	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::SPLIT_FACTOR_SIZE)] =
596	        static_cast<int32_t>(splitFactorSize);
597	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::SPLIT_FACTOR_TAIL_SIZE)] =
598	        static_cast<int32_t>(splitFactorTailSize);
599	
600	    // t1Size / t2Size: raw last element of actual_seq_lengths / actual_seq_lengths_kv
601	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::T1_SIZE)] = static_cast<int32_t>(t1Size_);
602	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::T2_SIZE)] = static_cast<int32_t>(t2Size_);
603	    metaDataPtr->baseMetadata[static_cast<uint32_t>(BaseMetaField::NEED_INIT)] = static_cast<int32_t>(needInit);
604	
605	    return true;
606	}
607	
608	REGISTER_CPU_KERNEL(K_AI_INFRA_ATTENTION_PIONEER_METADATA, AiInfraAttentionPioneerMetadataKernel);
609	} // namespace aicpu
