 * \brief MetaData constants and structure definitions for AiInfraAttentionPioneerMetadata AICPU operator.
 */

#ifndef AI_INFRA_ATTENTION_PIONEER_METADATA_H
#define AI_INFRA_ATTENTION_PIONEER_METADATA_H

#include <cstdint>

namespace optiling {

// A5 platform core numbers
constexpr uint32_t AP_AIC_CORE_NUM = 36;
constexpr uint32_t AP_AIV_CORE_NUM = 72;
constexpr uint32_t AP_CV_RATIO = AP_AIV_CORE_NUM / AP_AIC_CORE_NUM;
constexpr uint32_t AP_METADATA_SIZE = 1024;
using AP_METADATA_T = int32_t;

// Per-core layout: each core has SLOTS_PER_CORE reserved positions
constexpr uint32_t AP_SLOTS_PER_CORE = 10;

// Per-core field indices (within each core's slot)
enum class PerCoreField : uint32_t {
    AIC_CORE_ENABLE = 0,   // 0/1 enable flag
    BN2_START_PTR   = 1,   // batch*head start index
    GS1_START_PTR   = 2,   // sOuter block start index
    // indices 3..9 reserved
    K_COUNT         = AP_SLOTS_PER_CORE,
};

// Per-core section total size
constexpr uint32_t AP_PER_CORE_SECTION_SIZE = AP_AIC_CORE_NUM * AP_SLOTS_PER_CORE;

// Base metadata field indices (within baseMetadata array)
enum class BaseMetaField : uint32_t {
    USED_CORE_NUM                 = 0,   // cube cores actually used (before CV_RATIO)
    M_BASE_SIZE                   = 1,   // sOuterSize (M dimension tile size)
    S_INNER_SIZE                  = 2,   // sInnerSize (KV dimension tile size)
    S1_OUTER_SIZE                 = 3,   // total sOuter blocks
    S1_SIZE                       = 4,   // max Q sequence length
    S2_SIZE                       = 5,   // max KV sequence length
    ACTUAL_LEN_Q_DIM              = 6,   // actualSeqLengths Q dim count
    ACTUAL_LEN_KV_DIM             = 7,   // actualSeqLengths KV dim count
    MULTI_SMAX_S_INNER_LOOP_TIMES = 8,   // s2 direction loop count
    ACTUAL_CORE_NUMS              = 9,   // actual vector core num (= cube cores * CV_RATIO)
    TOTAL_SIZE                    = 10,  // total work size for multi-core split
    SPLIT_FACTOR_SIZE             = 11,  // work size per core
    SPLIT_FACTOR_TAIL_SIZE        = 12,  // tail core work size
    T1_SIZE                       = 13,  // t1Size: last element of actual_seq_lengths
    T2_SIZE                       = 14,  // t2Size: last element of actual_seq_lengths_kv
    NEED_INIT                     = 15,
    K_COUNT,                             // === 16; used to size baseMetadata array
};

// Base metadata field count (derived from enum sentinel to stay in sync automatically)
constexpr uint32_t AP_BASE_METADATA_SIZE = static_cast<uint32_t>(BaseMetaField::K_COUNT);

// Base metadata offset in flat array (right after per-core section)
constexpr uint32_t AP_BASE_OFFSET = AP_PER_CORE_SECTION_SIZE;

/**
 * Metadata layout (flat int32_t[1024]):
 *   [0..359]   Per-core data: 36 cores x 10 slots each
 *              Per core (core_id * 10 + offset):
 *                +0: AicCoreEnable  (0/1)
 *                +1: Bn2StartPtr    (batch*head start index)
 *                +2: Gs1StartPtr    (sOuter block start index)
 *                +3..9: reserved
 *   [360..375]  baseMetadata[16] - scalar parameters
 */
namespace detail {
struct APCoreSlot {
    int32_t fields[AP_SLOTS_PER_CORE];
};
struct APMetaData {
    APCoreSlot coreSlots[AP_AIC_CORE_NUM];
    int32_t baseMetadata[AP_BASE_METADATA_SIZE];
};
} // namespace detail

static_assert(AP_METADATA_SIZE * sizeof(AP_METADATA_T) >= sizeof(detail::APMetaData),
    "APMetaData must fit within AP_METADATA_SIZE int32_t elements");

// Flat access helper: get offset for a given core's field
inline constexpr uint32_t GetCoreFieldOffset(uint32_t coreIdx, PerCoreField field)
{
    return coreIdx * AP_SLOTS_PER_CORE + static_cast<uint32_t>(field);
}

#ifdef __CCE_AICORE__
__aicore__ inline uint32_t GetAPCoreEnable(uint32_t coreIdx)
{
    return GetCoreFieldOffset(coreIdx, PerCoreField::AIC_CORE_ENABLE);
}

__aicore__ inline uint32_t GetAPBnStartIdx(uint32_t coreIdx)
{
    return GetCoreFieldOffset(coreIdx, PerCoreField::BN2_START_PTR);
}

__aicore__ inline uint32_t GetAPGS1StartIdx(uint32_t coreIdx)
{
    return GetCoreFieldOffset(coreIdx, PerCoreField::GS1_START_PTR);
}

__aicore__ inline uint32_t GetAPBaseMetaIndex(BaseMetaField field)
{
    return AP_BASE_OFFSET + static_cast<uint32_t>(field);
}
#endif

} // namespace optiling

#endif // AI_INFRA_ATTENTION_PIONEER_METADATA_H

