/*!
 * \file aclnn_ai_infra_attention_pioneer_metadata.cpp
 * \brief aclnn API implementation for AiInfraAttentionPioneerMetadata AICPU operator.
 */

#include <string>
#include "aclnn_ai_infra_attention_pioneer_metadata.h"
#include "l0_ai_infra_attention_pioneer_metadata.h"
#include "aclnn_kernels/contiguous.h"
